import { useMemo } from "react";
import PortfolioService from "../services/PortfolioService";

/**
 * usePortfolioData
 * A custom hook to provide a consistent interface for UI components.
 * This abstraction layer allows for future shifts (e.g., to a live API or CMS)
 * without modifying the components themselves.
 *
 * Data is loaded synchronously from local JSON imports, so we use useMemo
 * instead of useEffect+useState to avoid a loading flicker on tab switches.
 */
export const usePortfolioData = () => {
    const data = useMemo(() => {
        try {
            return {
                projects: PortfolioService.getProjects(),
                experience: PortfolioService.getExperience(),
                techStack: PortfolioService.getTechStack(),
                involvements: PortfolioService.getInvolvements(),
                achievements: PortfolioService.getAchievements(),
                loading: false,
                error: null,
            };
        } catch (err) {
            return {
                projects: [],
                experience: [],
                techStack: [],
                involvements: [],
                achievements: [],
                loading: false,
                error: err,
            };
        }
    }, []);

    return data;
};

export default usePortfolioData;
